        self._stock = stock

    def restock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` units to a known product's stock and return the new level."""
        if self._catalog.get(sku) is None:
            raise ProductNotFound(sku)
        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)
        return new_level

    def fulfilment_summary(self) -> tuple[int, int, int]:
        """Return ``(open_orders, units_to_pick, low_stock_products)``.

        Open orders are those not cancelled; units are summed over those orders.
        Low stock uses the warehouse's 5-unit line.
        """
        open_orders = [o for o in self._orders.list_all() if o.status != "cancelled"]
        units = sum(item.quantity for o in open_orders for item in o.items)
        return len(open_orders), units, len(self.low_stock(LOW_STOCK_LINE))

    def low_stock(self, threshold: int) -> list[LowStockProduct]:
        """Active products with fewer than ``threshold`` units on hand, lowest first, then by SKU."""
        products = [LowStockProduct(p.sku, p.name, self._stock.get(p.sku))
                    for p in self._catalog.list_all() if p.active]
        low = [p for p in products if p.on_hand < threshold]
        return sorted(low, key=lambda p: (p.on_hand, p.sku))

    def packing_slip(self, order_id: str) -> PackingSlip:
        """Build the packing slip for a placed order.

        Raises OrderNotFound for an unknown order and Conflict for a cancelled one.
        """
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is cancelled")
        customer = self._customers.get(order.customer_id)
        if customer is None:
            raise CustomerNotFound(order.customer_id)
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            if product is None:
                raise ProductNotFound(item.sku)
            lines.append(PackingLine(item.sku, product.name, item.quantity))
        return PackingSlip(order.order_id, customer.name, tuple(lines))

